class Circle
    private define radius as integer;

    method constructor(aRadius as integer)
        this.radius <- aRadius;
    endMethod

    public method Perimeter() as real
        return 2 * this.radius * 3.14;
    endMethod

    public method Area() as real
        return this.radius * this.radius * 3.14;
    endMethod
endClass

algorithm ComputeCircle
    define radius as integer;
    define circle as Circle;
    read radius;
    circle <- new Circle(radius);
    write circle.Perimeter();
    write circle.Area();
endAlgorithm
